function checkWindowSize(windowSize) {
	if (typeof windowSize !== "number" || !Number.isInteger(windowSize) || windowSize < 1) {
		throw new RangeError("windowSize must be an integer of 1 or more");
	}
}

export class RollingMedian {
	/** @param {number} windowSize */
	constructor(windowSize) {
		checkWindowSize(windowSize);
		/** @type {number} */
		this.windowSize = windowSize;
		/** @type {number[]} oldest to newest */
		this.window = [];
	}

	/** @param {number} x @returns {number} */
	add(x) {
		if (typeof x !== "number" || !Number.isFinite(x)) {
			throw new TypeError("x must be a finite number");
		}
		this.window.push(x);
		if (this.window.length > this.windowSize) {
			this.window.shift();
		}
		return this.median();
	}

	/** @returns {number | null} */
	median() {
		const n = this.window.length;
		if (n === 0) return null;
		const sorted = [...this.window].sort((a, b) => a - b);
		return sorted[Math.floor((n - 1) / 2)];
	}

	/** @returns {number} */
	get size() {
		return this.window.length;
	}

	/** @returns {number[]} */
	values() {
		return [...this.window];
	}

	reset() {
		this.window = [];
		return undefined;
	}

	/** @param {number} n @returns {number | null} */
	resize(n) {
		checkWindowSize(n);
		this.windowSize = n;
		while (this.window.length > n) {
			this.window.shift();
		}
		return this.median();
	}
}

