import('./src/rolling-median.js').then(({RollingMedian: R}) => {
  const a = assert => { if (!assert) throw new Error('FAIL'); };
  // R1
  for (const bad of [0, -1, 1.5, '3', null, undefined, true, Infinity])
    a(() => { try { new R(bad); return false; } catch (e) { return e instanceof RangeError; } })();
  // R2
  const m = new R(2);
  m.add(1); m.add(2);
  for (const bad of [NaN, Infinity, -Infinity, '3', 1n, null, undefined, true]) {
    try { m.add(bad); a(false); } catch (e) { a(e instanceof TypeError); }
  }
  a(m.size === 2 && JSON.stringify(m.values()) === '[1,2]');
  a(m.add(5) === 2);            // even count -> lower middle of [1,2,5]
  a(m.add(4) === 4);            // window [5,4] -> lower of [4,5]
  // R3
  a(new R(3).median() === null);
  const e = new R(4);
  e.add(4); e.add(1); e.add(3); e.add(2);
  a(e.median() === 2);          // lower of 2,3
  // R4
  const v = m.values(); v.push(99);
  a(m.size === 2 && JSON.stringify(m.values()) === '[5,4]');
  // R5
  a(e.reset() === undefined && e.size === 0 && e.median() === null);
  a(e.add(7) === 7);
  // R6
  a(e.resize(3) === 7);
  try { e.resize(0); a(false); } catch (err) { a(err instanceof RangeError); }
  a(e.windowSize === 3 && e.size === 1);
  const g = new R(5);
  [1,2,3,4,5].forEach(x => g.add(x));
  a(g.resize(3) === 4);         // drops 1,2 -> [3,4,5]
  a(JSON.stringify(g.values()) === '[3,4,5]');
  g.add(6);                     // window size 3 now applies
  a(JSON.stringify(g.values()) === '[4,5,6]');
  const h = new R(2); h.add(1);
  a(h.resize(1) === null);      // shrink to empty? no: size 1 holds 1 -> median 1
  console.log('h.resize(1) =', h.resize(1));
  console.log('ALL OK');
});
